INSERT INTO dishes (name, description, full_description, price, image, category, tags, ingredients, available) VALUES
('和牛芝士汉堡', '澳洲M9和牛肉饼，搭配布里欧修面包', '选用澳洲M9级和牛肉手工打制肉饼，搭配焦糖洋葱、车达芝士与秘制松露酱，夹在新鲜烘烤的布里欧修面包中。每一口都是肉汁与香气的完美交融。', 128.00, '/dish-burger.jpg', 'signature', '["招牌", "人气"]', '["M9和牛肉", "布里欧修面包", "车达芝士", "焦糖洋葱", "松露酱"]', true),
('石锅拌饭', '传统韩式石锅，滋滋作响的锅巴香', '以300度高温石锅盛载，底层铺满金黄香脆的锅巴饭，上面整齐排列着时令蔬菜、澳洲牛肉丝与半熟太阳蛋，拌入秘制韩式辣酱，热气腾腾，色香味俱全。', 88.00, '/dish-bibimbap.jpg', 'main', '["热销", "辣味"]', '["优质大米", "澳洲牛肉", "时令蔬菜", "太阳蛋", "韩式辣酱"]', true),
('炭烤肋眼牛排', '美国Prime级肋眼，炭火慢烤', '精选美国USDA Prime级肋眼牛排，以果木炭火慢烤至完美熟度。外层焦香酥脆，内里粉嫩多汁，搭配迷迭香烤蒜与红酒酱汁，呈现最纯粹的肉食盛宴。', 368.00, '/dish-steak.jpg', 'signature', '["招牌", "推荐"]', '["USDA Prime肋眼", "迷迭香", "烤蒜", "红酒酱汁", "海盐"]', true),
('黑松露奶油意面', '新鲜黑松露片，浓郁奶油酱汁', '手工制作的宽扁意面，裹挟着以帕玛森芝士、鲜奶油与黄油熬制的浓郁酱汁，现刨新鲜黑松露薄片，香气扑鼻，口感丝滑，是松露爱好者的必点之选。', 168.00, '/dish-pasta.jpg', 'main', '["素食可选"]', '["手工意面", "黑松露", "帕玛森芝士", "鲜奶油", "黄油"]', true),
('香煎三文鱼', '挪威深海三文鱼，外酥里嫩', '来自挪威深海的顶级三文鱼，以低温慢煎锁住鲜美鱼油，鱼皮金黄酥脆，鱼肉鲜嫩多汁。搭配柠檬黄油汁与嫩豌豆苗，清新解腻，层次分明。', 158.00, '/dish-salmon.jpg', 'main', '["健康", "低卡"]', '["挪威三文鱼", "柠檬", "黄油", "豌豆苗", "橄榄油"]', true),
('熔岩巧克力蛋糕', '70%黑巧，切开后流心溢出', '采用70%法芙娜黑巧克力制作，外层松软绵密，切开后温热的巧克力流心缓缓溢出。搭配覆盆子果酱与香草冰淇淋，冷热交织，甜蜜满分。', 68.00, '/dish-dessert.jpg', 'dessert', '["必点", "甜蜜"]', '["法芙娜黑巧克力", "覆盆子", "香草冰淇淋", "金箔", "面粉"]', true),
('布拉塔芝士沙拉', '意大利进口布拉塔，配传家宝番茄', '从意大利空运而来的新鲜布拉塔芝士，切开后奶油内馅缓缓流出。搭配色彩斑斓的传家宝番茄、芝麻菜与陈年黑醋，简单纯粹却风味无穷。', 98.00, '/dish-salad.jpg', 'appetizer', '["轻食", "素食"]', '["布拉塔芝士", "传家宝番茄", "芝麻菜", "陈年黑醋", "橄榄油"]', true),
('那不勒斯披萨', '48小时低温发酵面团，果木烤制', '遵循传统那不勒斯工艺，面团经48小时低温发酵，在900度果木烤窑中90秒快速烤制。饼底薄脆有嚼劲，搭配圣马扎诺番茄、水牛马苏里拉与新鲜罗勒。', 108.00, '/dish-pizza.jpg', 'main', '["经典", "sharing"]', '["00号面粉", "圣马扎诺番茄", "水牛马苏里拉", "罗勒", "橄榄油"]', true),
('特选寿司拼盘', '当日空运鲜鱼，职人手握', '由拥有二十年经验的寿司职人现场手握制作。包含三文鱼、金枪鱼、鲷鱼、甜虾等多种当日空运鲜鱼，每一贯都是对食材与技艺的致敬。', 288.00, '/dish-sushi.jpg', 'signature', '["限量", "新鲜"]', '["三文鱼", "金枪鱼", "鲷鱼", "甜虾", "江户前赤醋饭"]', true),
('古典鸡尾酒', '波本威士忌，橙皮熏香', '以优质波本威士忌为基底，加入方糖与安哥斯图拉苦精，以大块手工切冰缓慢稀释，最后以橙皮熏香点缀。经典永不过时，每一口都是岁月的沉淀。', 88.00, '/dish-cocktail.jpg', 'drink', '["经典", "微醺"]', '["波本威士忌", "方糖", "安哥斯图拉苦精", "橙皮", "手工切冰"]', true),
('主厨甄选套餐', '7道式 tasting menu，每日限量', '由行政主厨精心设计的7道式品鉴菜单，从前菜到甜品，每道菜都是创意与技艺的结晶。菜单每月更换，使用当季最优质的食材，带来独一无二的用餐体验。', 688.00, '/dish-chef.jpg', 'signature', '["限量", "体验"]', '["当季食材", "主厨创意", "精选配酒"]', true),
('烤番茄浓汤', '慢烤樱桃番茄，浓郁酸甜', '精选枝上熟樱桃番茄，以橄榄油与海盐慢烤至焦糖化，再与新鲜罗勒一同打制浓汤。酸甜适中，口感丝滑，是开启一餐的完美序曲。', 58.00, '/dish-tomato.jpg', 'appetizer', '["暖胃", "素食"]', '["樱桃番茄", "罗勒", "橄榄油", "海盐", "奶油"]', true);
